class FeaturePackage(object):
    class Remote(object):
        """
        feature package information which is useful on the remote
        """

        @classmethod
        def from_dict(cls, remote_info):
            return cls(**remote_info)

        def __init__(self,
                     object_id,
                     server_package_name,
                     exposed_module_name,
                     exposed_class_name,
                     exposed_class_init_kwargs=None):
            """
            Initialize Remote information of feature package

            :param str object_id:   id representing exposed class or instance
            :param str server_package_name:   package name for server code, e.g. taf.xxx.xxx.server
            :param str exposed_module_name:   module name in which
            the being exposed class or class of exposed instance is
            :param str exposed_class_name:  name of being exposed class or class of exposed instance
            :param str exposed_class_init_kwargs:  kwargs when initialize exposed instance, must be as dict,
            like {'param1': value}
            """

            self._object_id = object_id
            self._server_package_name = server_package_name
            self._exposed_module_name = exposed_module_name
            self._exposed_class_name = exposed_class_name
            self._exposed_class_init_kwargs = exposed_class_init_kwargs

        @property
        def object_id(self):
            return self._object_id

        @property
        def server_package_name(self):
            return self._server_package_name

        @property
        def exposed_module_name(self):
            return self._exposed_module_name

        @property
        def exposed_class_name(self):
            return self._exposed_class_name

        @property
        def exposed_class_init_kwargs(self):
            return self._exposed_class_init_kwargs

        def to_dict(self):
            base_dict = {'object_id': self._object_id, 'server_package_name': self._server_package_name,
                         'exposed_module_name': self._exposed_module_name,
                         'exposed_class_name': self._exposed_class_name}
            if self._exposed_class_init_kwargs:
                base_dict.setdefault('exposed_class_init_kwargs', self._exposed_class_init_kwargs)
            return base_dict

    def __init__(self,
                 object_id,
                 server_package_name,
                 server_code_full_local_path,
                 exposed_module_name,
                 exposed_class_name,
                 exposed_class_init_kwargs=None):
        """
        Initialize information of feature package

        :param str object_id:   id representing exposed class or instance
        :param str server_package_name:   package name for server code, e.g. taf.xxx.xxx.server
        :param str server_code_full_local_path:   full path where the server code locates
        :param str exposed_module_name:   module name in which
        the being exposed class or class of exposed instance is
        :param str exposed_class_name:  name of being exposed class or class of exposed instance
        :param str exposed_class_init_kwargs:  kwargs when initialize exposed instance, must be as dict,
        like {'param1': value}
        """

        self._remote = self.Remote(object_id=object_id,
                                   server_package_name=server_package_name,
                                   exposed_module_name=exposed_module_name,
                                   exposed_class_name=exposed_class_name,
                                   exposed_class_init_kwargs=exposed_class_init_kwargs)
        self._server_code_full_local_path = server_code_full_local_path

    @property
    def server_code_full_local_path(self):
        return self._server_code_full_local_path

    @property
    def remote(self):
        return self._remote
